import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

PRIORITY_TIERS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL',
     'TOTAL', 'AMOUNT'],
]
EXCLUSIONS = ['SUBTOTAL', 'SUB TOTAL', 'SUB-TOTAL', 'TAX', 'GST', 'SST',
              'DISCOUNT', 'CHANGE', 'CASH TENDERED']

MONEY_RE = re.compile(r'(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.])')
# Lenient money regex: allows comma or small OCR noise in decimals part
MONEY_LENIENT = re.compile(r'(\d{1,3}(?:[,\s]?\d{3})*[.,][\dOolI|uG]{2})')

OCR_DIGIT_FIX = str.maketrans({'O': '0', 'o': '0', 'Q': '0', 'u': '0',
                                'l': '1', 'I': '1', '|': '1',
                                'S': '5', 'B': '8', 'G': '6', 'Z': '2'})


def normalize_amount_token(tok):
    tok = tok.replace(' ', '')
    # Replace comma used as decimal separator (e.g., "26,60") when
    # it's the only separator and 2 digits follow
    if ',' in tok and '.' not in tok:
        parts = tok.split(',')
        if len(parts[-1]) == 2:
            tok = tok.replace(',', '.')
    # Remove thousands separators
    if tok.count(',') >= 1 and '.' in tok:
        tok = tok.replace(',', '')
    # Confusable digit fixes in the numeric span
    numeric = re.sub(r'[^0-9.,]', '', tok.translate(OCR_DIGIT_FIX))
    m = MONEY_RE.search(numeric)
    if m:
        v = m.group(1).replace(',', '')
        try:
            return f"{float(v):.2f}"
        except ValueError:
            return None
    return None


def find_amount_in_line(line):
    """Find a monetary token in a line."""
    # Try strict regex first
    matches = MONEY_RE.findall(line)
    if matches:
        return normalize_amount_token(matches[-1])
    # Try lenient regex with OCR confusable fixes applied to numeric-looking spans
    # Fix only tokens dominated by digits
    tokens = re.findall(r'\S+', line)
    for tok in reversed(tokens):
        if sum(c.isdigit() for c in tok) >= 2:
            fixed = tok.translate(OCR_DIGIT_FIX)
            m = MONEY_RE.search(fixed)
            if m:
                return normalize_amount_token(m.group(1))
    return None


def line_canonical(line):
    s = re.sub(r'\s+', ' ', line.strip().upper())
    s = re.sub(r'[^\w\s:.$%()/-]', '', s)
    return s


def extract_total(text):
    lines = [ln for ln in text.split('\n') if ln.strip()]
    canon = [line_canonical(ln) for ln in lines]

    # Detect summary section cutoff (GST/TAX SUMMARY etc.)
    cutoff = len(lines)
    for i, c in enumerate(canon):
        if re.search(r'(GST|TAX|SST)\s*SUMMARY', c) or re.search(r'TAX\s*CODE', c):
            cutoff = i
            break

