    header_tokens = {'DESCRIPTION', 'ITEM', 'QTY', 'U.PRICE', 'UNIT PRICE', 'PRICE'}

    for tier in PRIORITY_TIERS:
        candidates = []
        for i in range(cutoff):
            c = canon[i]
            if not any(k in c for k in tier):
                continue
            if any(ex in c for ex in EXCLUSIONS):
                continue
            # Skip tabular headers
            toks = set(c.split())
            if toks & header_tokens:
                # If line contains header-like tokens co-occurring with TOTAL, skip
                continue
            candidates.append(i)
        # Walk from last to first
        for i in reversed(candidates):
            amt = find_amount_in_line(lines[i])
            if amt is not None:
                return amt
            # Guarded split-line fallback: keyword line has no digits
            if not re.search(r'\d', lines[i]) and i + 1 < len(lines):
                nxt_canon = canon[i + 1]
                if any(ex in nxt_canon for ex in EXCLUSIONS):
                    continue
                payment_kws = ['CASH', 'TENDERED', 'PAYMENT', 'PAID', 'RECEIVED',
                               'VISA', 'MASTERCARD', 'MASTER', 'CREDIT', 'DEBIT',
                               'CARD']
