DATE_PATTERNS = [
    re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})'),
    re.compile(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})'),
]
EXCLUDE_DATE_CTX = ('PRINT', 'CLOSED', 'CLOSING', 'FRN', 'LOYALTY', 'PROMO',
                    'EXPIRY', 'EXP')


def parse_date_components(a, b, c):
    """Try to interpret as (day, month, year) with DD/MM/YYYY first."""
    a, b, c = int(a), int(b), int(c)
    # Year normalization: if year is 2 digits, pad
    def ymd(d, m, y):
        if y < 100:
            y = 2000 + y if y < 70 else 1900 + y
        return d, m, y
    # Try DD/MM/YY first (Malaysian receipts)
    cands = []
    # If first number is >12, must be DD/MM/YY
    if a > 12 and b <= 12:
        d, m, y = ymd(a, b, c)
        cands.append((d, m, y, 'dmy'))
    elif b > 12 and a <= 12:
        d, m, y = ymd(b, a, c)
        cands.append((d, m, y, 'mdy'))
    elif c > 31:  # YYYY-MM-DD
        d, m, y = ymd(c, b, a) if False else (int(c), int(b), int(a))
        # Interpret as a=year? Not applicable in these patterns
        d, m, y = ymd(a, b, c)
        cands.append((d, m, y, 'dmy'))
    else:
        # Prefer DD/MM/YY
        d, m, y = ymd(a, b, c)
        cands.append((d, m, y, 'dmy'))
    # Validate
    import datetime
    for d, m, y, _ in cands:
        try:
            datetime.date(y, m, d)
            if 2000 <= y <= 2030:
                return f"{y:04d}-{m:02d}-{d:02d}"
        except ValueError:
            continue
    return None


def extract_date(text):
    lines = [ln for ln in text.split('\n') if ln.strip()]
    # Pass 1: lines with DATE label
    labeled_candidates = []
    unlabeled_candidates = []
    for ln in lines:
        up = ln.upper()
        if any(bad in up for bad in EXCLUDE_DATE_CTX):
            continue
        has_label = bool(DATE_LABEL_RE.search(ln))
        for pat in DATE_PATTERNS:
            for m in pat.finditer(ln):
                g = m.groups()
                # Determine order based on which pattern
                if len(g[0]) == 4:  # YYYY-MM-DD
                    import datetime
                    try:
                        y, mo, d = int(g[0]), int(g[1]), int(g[2])
                        datetime.date(y, mo, d)
                        iso = f"{y:04d}-{mo:02d}-{d:02d}"
                    except ValueError:
                        continue
                else:
                    iso = parse_date_components(g[0], g[1], g[2])
                if iso:
                    (labeled_candidates if has_label else unlabeled_candidates).append(iso)
    if labeled_candidates:
        return labeled_candidates[0]
    if unlabeled_candidates:
        return unlabeled_candidates[0]
    return None


def ocr_variants(img):
    variants_text = []
    gray = ImageOps.grayscale(img)
    for scale in [1, 2]:
        if scale == 1:
            g = gray
        else:
            g = gray.resize((gray.width*scale, gray.height*scale))
        g2 = ImageOps.autocontrast(g)
        for psm in [6, 4, 11]:
            try:
                txt = pytesseract.image_to_string(g2, config=f'--psm {psm}')
                variants_text.append(txt)
            except Exception:
                pass
    return variants_text


def process_image(path):
    img = Image.open(path)
    variants = ocr_variants(img)

    # Try to extract total/date from each variant and vote
    totals = []
    dates = []
    for txt in variants:
        t = extract_total(txt)
        d = extract_date(txt)
        if t:
            totals.append(t)
        if d:
            dates.append(d)

    # Pick most common
    def most_common(lst):
        if not lst:
            return None
        from collections import Counter
        return Counter(lst).most_common(1)[0][0]

    return most_common(dates), most_common(totals)


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])

