DATE_LABEL_RE = re.compile(r'\b(DATE|DATA|DAIE)\b', re.IGNORECASE)
DATE_PATTERNS = [
    re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})'),
    re.compile(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})'),
]
EXCLUDE_DATE_SUBSTR = ('PRINT DATE', 'PRINT TIME', 'CLOSED', 'CLOSING',
                      'EXPIRY', 'EXP DATE', 'LOYALTY', 'PROMO')


def _valid_date(y, m, d):
    try:
        datetime.date(y, m, d)
        return 2000 <= y <= 2030
    except ValueError:
        return False


def parse_date_components(a, b, c):
    a, b, c = int(a), int(b), int(c)
    if c < 100:
        c = 2000 + c if c < 70 else 1900 + c
    if _valid_date(c, b, a):
        return f"{c:04d}-{b:02d}-{a:02d}"
    if _valid_date(c, a, b):
        return f"{c:04d}-{a:02d}-{b:02d}"
    return None


def extract_date_candidates(text):
    lines = [ln for ln in text.split('\n') if ln.strip()]
    results = []
    for ln in lines:
        up = canonical(ln)
        if any(bad in up for bad in EXCLUDE_DATE_SUBSTR):
            continue
        has_label = bool(DATE_LABEL_RE.search(ln))
        for pat in DATE_PATTERNS:
            for m in pat.finditer(ln):
                g = m.groups()
                if len(g[0]) == 4:
                    y, mo, d = int(g[0]), int(g[1]), int(g[2])
                    if _valid_date(y, mo, d):
                        results.append((f"{y:04d}-{mo:02d}-{d:02d}", has_label))
                else:
                    iso = parse_date_components(g[0], g[1], g[2])
                    if iso:
                        results.append((iso, has_label))
    return results


def ocr_variants(img):
    out = []
    gray = ImageOps.grayscale(img)
    for scale in [1, 2]:
        g = gray if scale == 1 else gray.resize((gray.width*scale, gray.height*scale))
        g2 = ImageOps.autocontrast(g)
        for psm in [6, 4, 11]:
            try:
                out.append(pytesseract.image_to_string(g2, config=f'--psm {psm}'))
            except Exception:
                pass
    return out


def pick_date(all_candidates):
    labeled, unlabeled = [], []
    for variant_list in all_candidates:
        for iso, has_label in variant_list:
            (labeled if has_label else unlabeled).append(iso)
    if labeled:
        return Counter(labeled).most_common(1)[0][0]
    if unlabeled:
        return Counter(unlabeled).most_common(1)[0][0]
    return None


def pick_total(totals):
    if not totals:
        return None
    return Counter(totals).most_common(1)[0][0]


def process_image(path, debug=False):
    img = Image.open(path)
    variants = ocr_variants(img)
    totals = []
    date_lists = []
    for txt in variants:
        t = extract_total(txt)
        if t:
            totals.append(t)
        date_lists.append(extract_date_candidates(txt))
    if debug:
        print('  totals:', totals)
        print('  dates:', date_lists)
    return pick_date(date_lists), pick_total(totals)


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    files = sorted(f for f in os.listdir(IMG_DIR)
                   if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    debug = '--debug' in sys.argv
    for f in files:
        date, total = process_image(os.path.join(IMG_DIR, f), debug=debug)
        print(f, date, total)
        ws.append([f, date, total])
    wb.save(OUT_PATH)
    print('Saved', OUT_PATH)


if __name__ == '__main__':
    main()
